  _A_ROUTER_LINK_CONFIG_LABEL_QUERY_: qde,
  _A_ROUTER_LINK_CONFIG_LABEL_ROUTE_: kde,
  _A_ROUTER_LINK_CONFIG_LABEL_TARGET_: Wde,
